export const BT_REGEX=new RegExp("blu[e]?[ ]?toot[h]?|\\bb[ ]?t\\b|\\bble\\b|\\bfloss\\b|\\bbluez\\b","i");export const WIFI_REGEX=buildWordMatcher(["wifi","wi-fi","internet","network","hotspot"]);export const CELLULAR_REGEX=buildWordMatcher(["2G","3G","4G","5G","LTE","UMTS","SIM","eSIM","mmWave","mobile","APN","IMEI","IMSI","eUICC","carrier","T.Mobile","TMO","Verizon","VZW","AT&T","MVNO","pin.lock","cellular"]);export const DISPLAY_REGEX=buildWordMatcher(["display","displayport","hdmi","monitor","panel","screen"]);export const USB_REGEX=buildWordMatcher(["USB","USB-C","Type-C","TypeC","USBC","USBTypeC","USBPD","hub","charger","dock"]);export const THUNDERBOLT_REGEX=buildWordMatcher(["Thunderbolt","Thunderbolt3","Thunderbolt4","TBT","TBT3","TBT4","TB3","TB4"]);export const CANNOT_CONNECT_REGEX=new RegExp("((headphone|keyboard|mouse|speaker)((?!(connect|pair)).*)(connect|pair))"+"|((connect|pair).*(headphone|keyboard|mouse|speaker))","i");export const TETHER_REGEX=new RegExp("tether(ing)?","i");export const SMART_LOCK_REGEX=new RegExp("(smart|easy)[ ]?(un)?lock","i");export const NEARBY_SHARE_REGEX=new RegExp("nearby|phone","i");export const FAST_PAIR_REGEX=new RegExp("fast[ ]?pair","i");export const BT_DEVICE_REGEX=buildWordMatcher(["apple","allegro","pixelbud","microsoft","sony"]);function buildWordMatcher(words){return new RegExp(words.map((word=>"\\b"+word+"\\b[^$]")).join("|"),"i")}